/** Verifies exact native expression decoding and its dictionary-read cost against real compressed store records. */
@Isolated("Observes the native codec's process-wide dictionary-read counter")
class LmdbNativeValueOverlayTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@TempDir
	File directory;

	private ValueStore store;

	@BeforeEach
	void openStore() throws Exception {
		store = new ValueStore(new File(directory, "values"), new LmdbStoreConfig().setInlineLiterals(false));
	}

	@AfterEach
	void closeStore() throws Exception {
		store.close();
	}

	@Test
	void coveredStoredLiteralAvoidsNativeDictionaryReads() throws Exception {
		Literal value = VF.createLiteral("A stored lexical value covered by the compressed overlay");
		long id = storeValues(List.of(value))[0];
		assertFalse(ValueIds.isInlined(id));
		store.warmCompressedValueOverlay(options(1 << 20));

		assertCovered(id, value);
	}

	@Test
	void coveredRecordsPreserveKindsMetadataAndCompressedUtf8() throws Exception {
		List<Value> values = new ArrayList<>(List.of(
				VF.createLiteral(""),
				VF.createLiteral("é/e\u0301/漢字/😀", "nB"),
				VF.createLiteral("مرحبا/漢字/😀", "ar", Literal.BaseDirection.RTL),
				VF.createLiteral("é/e\u0301/English", "en", Literal.BaseDirection.LTR),
				VF.createLiteral("+00000121", XSD.INTEGER),
				VF.createLiteral("-00012.34000", XSD.DECIMAL),
				VF.createLiteral("2026-09-11T12:00:00.000+02:00", XSD.DATETIME),
				VF.createLiteral("custom lexical 漢字", VF.createIRI("https://example.org/datatypes/custom")),
				VF.createIRI("https://example.org/namespace/é/漢字/😀"),
				VF.createBNode("blank-node-é")));
		for (int i = 0; i < 256; i++) {
			values.add(VF.createLiteral("é/e\u0301/漢字/" + "shared long lexical prefix ".repeat(45) + i, "nB"));
		}
		long[] ids = storeValues(values);
		CompressedValueOverlay.Stats stats = store.warmCompressedValueOverlay(options(1 << 20));
		assertTrue(stats.prefixPages() > 0, "Exercise selective access to compressed shared-prefix records");
		assertEquals(0, stats.skippedLargeRecords());

		for (int i = 0; i < ids.length; i++) {
			assertCovered(ids[i], values.get(i));
		}
	}

	@Test
	void absentOverlayRetainsNativeFallback() throws Exception {
		Value value = VF.createIRI("https://example.org/native-fallback/漢字");
		long id = storeValues(List.of(value))[0];
		assertNull(store.compressedValueOverlayStats());

		assertNativeFallback(id, value);
	}

	@Test
	void nullOverlayResultIsAHitAndTypedRecordCannotEscape() throws Exception {
		long id = storeValues(List.of(VF.createBNode("callback-scoped")))[0];
		store.warmCompressedValueOverlay(options(1 << 20));
		ValueStoreRecordVisitor.Record[] retained = new ValueStoreRecordVisitor.Record[1];

		Object result = store.withData(id, (address, length) -> fail("Covered null result must not fall back"),
				record -> {
					retained[0] = record;
					return null;
				});

		assertNull(result);
		assertNotNull(retained[0]);
		assertThrows(IllegalStateException.class, retained[0]::kind);
		// Existing pointer-only callers still receive native records even when the overlay is populated.
		boolean nativeRecord = store.withData(id, (address, length) -> address != 0 && length > 0);
		assertTrue(nativeRecord);
	}

	@Test
	void overlayRemainsPinnedUntilCallbackCompletes() throws Exception {
		String label = "pinned-compressed-record";
		long id = storeValues(List.of(VF.createBNode(label)))[0];
		store.warmCompressedValueOverlay(options(1 << 20));

		String result = store.withData(id, (address, length) -> fail("Covered record must not fall back"), record -> {
			store.clearCompressedValueOverlay();
			byte[] bytes = new byte[record.lexicalByteLength()];
			record.copyLexical(0, bytes, 0, bytes.length);
			return new String(bytes, StandardCharsets.UTF_8);
		});

		assertEquals(label, result);
		assertNull(store.compressedValueOverlayStats());
		assertNativeFallback(id, VF.createBNode(label));
	}

	@Test
	void throwingOverlayReaderInvalidatesItsRecord() throws Exception {
		long id = storeValues(List.of(VF.createBNode("throwing-reader")))[0];
		store.warmCompressedValueOverlay(options(1 << 20));
		ValueStoreRecordVisitor.Record[] retained = new ValueStoreRecordVisitor.Record[1];
		IllegalArgumentException failure = new IllegalArgumentException("reader failure");

		IllegalArgumentException actual = assertThrows(IllegalArgumentException.class,
				() -> store.withData(id, (address, length) -> fail("Covered record must not fall back"), record -> {
					retained[0] = record;
					throw failure;
				}));

		assertSame(failure, actual);
		assertNotNull(retained[0]);
		assertThrows(IllegalStateException.class, retained[0]::kind);
		assertCovered(id, VF.createBNode("throwing-reader"));
	}

	@Test
	void missingRecordInvokesNeitherReader() throws Exception {
		storeValues(List.of(VF.createBNode("retained")));
		store.warmCompressedValueOverlay(options(1 << 20));
		store.startTransaction(true);
		long missingId = store.storeValue(VF.createBNode("rolled-back-missing"));
		store.rollback();

		Object result = store.withData(missingId, (address, length) -> fail("Missing native record"),
				record -> fail("Missing overlay record"));

		assertNull(result);
	}

	@Test
	void oversizedUncoveredRecordRetainsNativeFallback() throws Exception {
		Value covered = VF.createBNode("covered");
		Value oversized = VF.createLiteral("large lexical 漢字/😀 ".repeat(100));
		long[] ids = storeValues(List.of(covered, oversized));
		CompressedValueOverlay.Stats stats = store.warmCompressedValueOverlay(options(64));
		assertTrue(stats.skippedLargeRecords() > 0);

		assertNativeFallback(ids[1], oversized);
		assertCovered(ids[0], covered);
	}

	@Test
	void owningWriterUsesNativeRecordsAndCommitPublishesCoveredDelta() throws Exception {
		Value original = VF.createLiteral("original stored value");
		long originalId = storeValues(List.of(original))[0];
		store.warmCompressedValueOverlay(options(1 << 20));
		Value committed = VF.createLiteral("committed stored value", "en", Literal.BaseDirection.LTR);

		store.startTransaction(true);
		long committedId = store.storeValue(committed);
		assertNativeFallback(originalId, original);
		assertNativeFallback(committedId, committed);
		store.commit();

		assertCovered(originalId, original);
		assertCovered(committedId, committed);
	}

	@Test
	void rollbackAndClearKeepOverlayVisibilityExact() throws Exception {
		Value original = VF.createBNode("before-rollback");
		long originalId = storeValues(List.of(original))[0];
		store.warmCompressedValueOverlay(options(1 << 20));
		Value rolledBack = VF.createBNode("rolled-back");
		store.startTransaction(true);
		long rolledBackId = store.storeValue(rolledBack);
		assertNativeFallback(rolledBackId, rolledBack);
		store.rollback();

		assertTrue(new LmdbNativeValueCodec(store).decode(rolledBackId).error());
		assertCovered(originalId, original);
		store.clear();
		assertNull(store.compressedValueOverlayStats());
		Value replacement = VF.createBNode("after-clear");
		long replacementId = storeValues(List.of(replacement))[0];
		assertNativeFallback(replacementId, replacement);
		store.warmCompressedValueOverlay(options(1 << 20));
		assertCovered(replacementId, replacement);
	}

	@Test
	void inlineValuesBypassDictionaryWithAndWithoutOverlay() throws Exception {
		ValueStore inlineStore = new ValueStore(new File(directory, "inline"),
				new LmdbStoreConfig().setInlineLiterals(true));
		try {
			List<Value> values = List.of(VF.createLiteral("alpha"), VF.createLiteral(true), VF.createLiteral(42));
			long[] ids = new long[values.size()];
			inlineStore.startTransaction(true);
			for (int i = 0; i < ids.length; i++) {
				ids[i] = inlineStore.storeValue(values.get(i));
				assertTrue(ValueIds.isInlined(ids[i]));
			}
			inlineStore.commit();
			long before = LmdbNativeValueCodec.ZERO_COPY_READS.get();
			for (int i = 0; i < ids.length; i++) {
				assertDecoded(new LmdbNativeValueCodec(inlineStore), ids[i], values.get(i));
			}
			assertEquals(before, LmdbNativeValueCodec.ZERO_COPY_READS.get());

			inlineStore.warmCompressedValueOverlay(options(1 << 20));
			for (int i = 0; i < ids.length; i++) {
				assertDecoded(new LmdbNativeValueCodec(inlineStore), ids[i], values.get(i));
			}
			assertEquals(before, LmdbNativeValueCodec.ZERO_COPY_READS.get());
		} finally {
			inlineStore.close();
		}
	}

	@Test
	@Timeout(60)
	void concurrentDecodesKeepCompressedPayloadsOwnedByTheirInvocation() throws Exception {
		List<Value> values = new ArrayList<>();
		for (int i = 0; i < 256; i++) {
			values.add(VF.createLiteral("shared compressed é/漢字/😀 ".repeat(20) + i, "en",
					i % 2 == 0 ? Literal.BaseDirection.LTR : Literal.BaseDirection.RTL));
		}
		long[] ids = storeValues(values);
		store.warmCompressedValueOverlay(options(1 << 20));
		LmdbNativeValueCodec codec = new LmdbNativeValueCodec(store);
		long before = LmdbNativeValueCodec.ZERO_COPY_READS.get();
		CountDownLatch start = new CountDownLatch(1);
		try (var executor = Executors.newFixedThreadPool(4)) {
			List<Future<?>> results = new ArrayList<>();
			for (int worker = 0; worker < 4; worker++) {
				int rotation = worker * 61;
				results.add(executor.submit(() -> {
					start.await();
					for (int pass = 0; pass < 8; pass++) {
						for (int j = 0; j < ids.length; j++) {
							int index = (j + rotation + pass) % ids.length;
							assertDecoded(codec, ids[index], values.get(index));
						}
					}
					return null;
				}));
			}
			start.countDown();
			for (Future<?> result : results) {
				result.get(30, TimeUnit.SECONDS);
			}
		}
		assertEquals(before, LmdbNativeValueCodec.ZERO_COPY_READS.get());
	}

	private long[] storeValues(List<Value> values) throws Exception {
		long[] ids = new long[values.size()];
		store.startTransaction(true);
		for (int i = 0; i < ids.length; i++) {
			ids[i] = store.storeValue(values.get(i));
		}
		store.commit();
		return ids;
	}

	private static CompressedValueOverlay.Options options(int maxRecordBytes) {
		return new CompressedValueOverlay.Options(32L << 20, 8192, 16, 64 << 10, maxRecordBytes, true, true);
	}

	private void assertCovered(long id, Value expected) {
		long before = LmdbNativeValueCodec.ZERO_COPY_READS.get();
		assertDecoded(new LmdbNativeValueCodec(store), id, expected);
		assertEquals(before, LmdbNativeValueCodec.ZERO_COPY_READS.get(),
				"A covered record and its datatype/namespace must decode without native dictionary reads");
	}

	private void assertNativeFallback(long id, Value expected) {
		long before = LmdbNativeValueCodec.ZERO_COPY_READS.get();
		assertDecoded(new LmdbNativeValueCodec(store), id, expected);
		assertTrue(LmdbNativeValueCodec.ZERO_COPY_READS.get() > before,
				"The unavailable overlay must retain the native dictionary fallback");
	}

	private static void assertDecoded(LmdbNativeValueCodec codec, long id, Value expected) {
		LmdbNativeValueCodec.DecodedValue decoded = codec.decode(id);
		assertFalse(decoded.error(), "Stored value must decode: " + expected);
		Value actual = LmdbNativeValueCodec.toValue(decoded);
		assertNotNull(actual);
		assertEquals(expected, actual);
		if (expected instanceof Literal literal) {
			assertEquals(literal.getLabel(), decoded.label());
			assertEquals(literal.getLanguage(), decoded.language());
			assertEquals(literal.getBaseDirection(), decoded.baseDirection());
			assertEquals(literal.getDatatype().stringValue(), decoded.datatypeIri());
		}
	}
}
